import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Widget","description":"","frontmatter":{},"headers":[],"relativePath":"zh/api/widget.md","filePath":"zh/api/widget.md","lastUpdated":1786971590000}'),r={name:"zh/api/widget.md"};function i(l,t,c,n,h,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="widget" tabindex="-1">Widget <a class="header-anchor" href="#widget" aria-label="Permalink to &quot;Widget&quot;">​</a></h1><p>所有 UI 组件的抽象基类。</p><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>Widget</code> 是 NeoFlux Widget 系统的基类。每个 Widget 绑定一个 Taitank 布局节点，支持子组件、事件处理和自定义绘制。</p><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>Build(ctx) -&gt; std::shared_ptr&lt;Widget&gt;</code></td><td>构建子组件树，默认返回 nullptr</td></tr><tr><td><code>Paint(ctx)</code></td><td>自定义绘制，默认绘制背景和子组件</td></tr><tr><td><code>OnMeasure(width, height) -&gt; Size</code></td><td>报告固有尺寸，叶子组件必须重写</td></tr><tr><td><code>AddChild(child)</code></td><td>添加子组件</td></tr><tr><td><code>ClearChildren()</code></td><td>清除所有子组件</td></tr><tr><td><code>GetChildren() -&gt; const vector&amp;</code></td><td>获取子组件列表</td></tr><tr><td><code>MarkNeedsBuild()</code></td><td>标记需要重建</td></tr><tr><td><code>NeedsBuild() -&gt; bool</code></td><td>是否需要重建</td></tr><tr><td><code>ClearNeedsBuild()</code></td><td>清除重建标记</td></tr></tbody></table><h2 id="事件处理" tabindex="-1">事件处理 <a class="header-anchor" href="#事件处理" aria-label="Permalink to &quot;事件处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>OnPointerDown(pos) -&gt; bool</code></td><td>指针按下</td></tr><tr><td><code>OnPointerUp(pos)</code></td><td>指针释放</td></tr><tr><td><code>OnPointerMove(pos) -&gt; bool</code></td><td>指针移动</td></tr><tr><td><code>OnPointerEnter()</code></td><td>指针进入</td></tr><tr><td><code>OnPointerExit()</code></td><td>指针离开</td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>SetState(state)</code></td><td>设置 Widget 状态，触发 OnStateChanged</td></tr><tr><td><code>GetState() -&gt; WidgetState</code></td><td>获取当前状态</td></tr><tr><td><code>OnStateChanged(from, to)</code></td><td>状态变化回调</td></tr></tbody></table><h2 id="布局属性" tabindex="-1">布局属性 <a class="header-anchor" href="#布局属性" aria-label="Permalink to &quot;布局属性&quot;">​</a></h2><ul><li><code>SetFlexDirection(direction)</code></li><li><code>SetJustifyContent(align)</code></li><li><code>SetAlignItems(align)</code></li><li><code>SetPadding(insets)</code></li><li><code>SetMargin(insets)</code></li><li><code>SetWidth(width)</code> / <code>SetHeight(height)</code></li><li><code>SetBackgroundColor(color)</code></li><li><code>SetBorderRadius(radius)</code></li></ul><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./container">Container</a></li><li><a href="./stateful">StatefulWidget</a></li></ul>',14)])])}const b=e(r,[["render",i]]);export{u as __pageData,b as default};
